,p_plug_display_sequence=>20
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    id,',
'    (',
'        CASE',
'            WHEN nvl(containersno, 0) = 0 THEN',
'                NULL',
'            ELSE',
'                ''<span class="fa fa-eye" aria-hidden="true"></span>''',
'        END',
'    ) more,',
'    name,',
'    auctionsno,',
'    containersno,',
'    successfulauctionsno,',
'    pendingauctionsno,',
unistr('    DECODE (sellerCategory , ''REAL_ESTATES'', decode(nvl(:P_LANG, ''ar''),''ar'',''\0639\0642\0627\0631\0627\062A'' ,''REAL ESTATES''), '),
unistr('                             ''VEHICLES'', decode(nvl(:P_LANG, ''ar''),''ar'',''\0645\0646\0642\0648\0644\0627\062A'' ,''VEHICLES''), '),
unistr('                             ''ANIMALS'', decode(nvl(:P_LANG, ''ar''),''ar'',''\062D\064A\0648\0627\0646\0627\062A'' ,''ANIMALS''), '),
'                             ''''',
'    ) AS sellerCategory,',
'    AuctionsNotpayed  ,',
'    ProductsNotpayed ,',
'    null chat,',
'    trunc(LastAuctionContainerDate) LastAuctionContainerDate,',
'    LastAuctionContainerDate LastAuctionDate,',
'    (CASE WHEN trunc(LastAuctionContainerDate) <= trunc(sysdate)      and trunc(LastAuctionContainerDate) > trunc(sysdate - 30) THEN ''u-success-bg'' ',
'          WHEN trunc(LastAuctionContainerDate) <= trunc(sysdate - 30 )and trunc(LastAuctionContainerDate) > trunc(sysdate - 60) THEN ''u-warning-bg'' ',
'          WHEN trunc(LastAuctionContainerDate) <= trunc(sysdate - 60 )and trunc(LastAuctionContainerDate) > trunc(sysdate - 90) THEN ''u-color-8-bg'' ',
'          ELSE ''u-danger-bg''',
'     END ',
'    ) status,',
'    round(SUM(nvl(successfulauctionsno, 0)) / SUM(',
'        CASE',
'            WHEN auctionsno IS NULL',
'                 OR auctionsno = 0 THEN',
'                1',
'            ELSE',
'                auctionsno',
'        END',
'    ) * 100, 3) || '' % '' sale_percentage',
'FROM',
'    TABLE ( get_sellers_data )',
'GROUP BY',
'    id,',
'    name,',
'    auctionsno,',
'    containersno,',
'    successfulauctionsno,',
'    pendingauctionsno,',
'    sellerCategory,',
'     AuctionsNotpayed,',
'    ProductsNotpayed,',
'    LastAuctionContainerDate',
'',
'',
'-- OTHER WAY TO RETRAIVE THE DATA',
'-- SELECT jt.id, ',
'--        jt.name, ',
'--        jt.auctionsno,',
'--        ( CASE WHEN nvl(jt.containersno, 0) = 0 THEN NULL',
'--             ELSE ''<span class="fa fa-eye" aria-hidden="true"></span>''',
'--          END',
'--         ) more,',
'--        jt.containersno,',
'--        jt.successfulauctionsno, ',
'--        jt.pendingauctionsno, ',
'--        trunc(jt.LastAuctionContainerDate) LastAuctionContainerDate,',
'--        jt.sellerCategory, ',
'--        jt.AuctionsNotpayed, ',
'--        jt.ProductsNotpayed,',
'--        null chat,',
'--        jt.LastAuctionContainerDate AS LastAuctionDate,',
'--        (CASE',
'--             WHEN trunc(jt.LastAuctionContainerDate) <= trunc(sysdate) AND trunc(jt.LastAuctionContainerDate) > trunc(sysdate - 30) THEN ''u-success-bg'' ',
'--             WHEN trunc(jt.LastAuctionContainerDate) <= trunc(sysdate - 30 ) AND trunc(jt.LastAuctionContainerDate) > trunc(sysdate - 60) THEN ''u-warning-bg'' ',
'--             WHEN trunc(jt.LastAuctionContainerDate) <= trunc(sysdate - 60 ) AND trunc(jt.LastAuctionContainerDate) > trunc(sysdate - 90) THEN ''u-color-8-bg'' ',
'--             ELSE ''u-danger-bg''',
'--          END ',
'--         ) status,',
'--         round(SUM(nvl(successfulauctionsno, 0)) / SUM (',
'--          CASE',
'--             WHEN auctionsno IS NULL OR auctionsno = 0 THEN 1',
'--             ELSE auctionsno',
'--          END',
'--         ) * 100, 3) || '' % '' AS sale_percentage',
'--   FROM JSON_TABLE (:P14_RESPONSE, ''$.sellers[*]''',
'--         COLUMNS ( ',
'--             id NUMBER PATH ''$.id'', ',
'--             name VARCHAR2 ( 300 ) PATH ''$.name'', ',
'--             auctionsno NUMBER PATH ''$.auctionsNo'', ',
'--             containersno NUMBER PATH ''$.containersNo'', ',
'--             successfulauctionsno NUMBER PATH ''$.successfulAuctionsNo'', ',
'--             pendingauctionsno NUMBER PATH ''$.pendingAuctionsNo'', ',
'--             LastAuctionContainerDate TIMESTAMP PATH ''$.LastAuctionContainerDate'', ',
'--             sellerCategory VARCHAR2 ( 300 ) PATH ''$.sellerCategory'', ',
'--             AuctionsNotpayed number PATH ''$.paymentIncompleteContainersNo'', ',
'--             ProductsNotpayed  number PATH ''$.paymentIncompleteAuctionsNo'' ',
'--         ) ',
'--     ) jt',
'--  GROUP BY jt.id, jt.name, jt.auctionsno, jt.containersno, jt.successfulauctionsno, jt.pendingauctionsno, jt.sellerCategory, jt.AuctionsNotpayed, jt.ProductsNotpayed, jt.LastAuctionContainerDate'))
,p_plug_source_type=>'NATIVE_IR'
