,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Get data'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_result    CLOB; ',
'    G_BASE_URL  VARCHAR2(5000) := SYSTEM_CONTROLS.SYS_CONFIG_VALUE(P_KEY => ''base_url'');',
'    l_url       VARCHAR2(4000) := G_BASE_URL || ''/apex/sellers''; ',
'BEGIN ',
'    l_result := APEX_WEB_SERVICE.make_rest_request (p_url => l_url, p_http_method => ''GET'');',
'',
'    IF APEX_WEB_SERVICE.g_status_code NOT IN ( 200, 201, 202, 203, 204, 205, 206, 207, 226 ) THEN',
'        SYSTEM_CONTROLS.error_logs( p_ERROR_TYPE => ''GET_SELLER_DATA'',',
'                                    p_PROCESS_NAME => ''APP132_PAGE14.beforeHeaderProcess'',',
'                                    p_ERROR_CODE => -2,',
'                                    p_ERROR_MESSAGE => SUBSTR(l_result, 1, 4000),',
'                                    p_OBJECT_TYPE => '''',',
'                                    p_logger_name => USER',
'                                );',
'',
'        RAISE_APPLICATION_ERROR (-20007, SUBSTR(l_result, 1, 4000) || '' - Status: '' || APEX_WEB_SERVICE.g_status_code);',
'    END IF;',
'',
'    :P14_RESPONSE := SUBSTR(l_result, 1, 4000);',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>23716262122221050
);
end;
