,p_plug_display_sequence=>60
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT status,',
'       product_id,',
'       buyer,',
'       ar_sa,',
'       sakNo,',
unistr('       regexp_replace( extract_varchar(ar_sa),''(\0631\0642\0645 \0627\0644\0635\0643|\0631\0642\0645 \0635\0643)'', '''' ) AS Product_Name,'),
'       startprice,',
'       lastbid,',
'       paymentstatus,',
'       subtotal,',
'       totalprice,',
'       totaldiscount,',
'       (case when istransfertoinfath = ''true'' then ''u-success-bg'' else ''u-warning-bg'' end ) istransfertoinfath_color ,',
'       nvl(istransfertoinfath,''false'') istransfertoinfath ,',
unistr('       SUM((case when item_ar_SA like ''%\0633\0639\0631 \0627\0644\0631\0628\062D%'' then nvl(item_totalPrice,0) else 0 end))   won_price,'),
unistr('       SUM((CASE WHEN item_ar_sa LIKE ''%\0633\0639\064A%'' THEN nvl( item_totalprice, 0) ELSE 0 END )) agent_price,'),
'       (CASE WHEN status LIKE ''%SOLD%''  THEN ''<span aria-hidden="true" class="fa fa-clipboard-list"></span>'' ELSE null END ) details ,',
'       (CASE WHEN status LIKE ''%SOLD%'' THEN ''u-success-bg'' when status LIKE ''%LIVE_NOW%'' then ''u-warning-bg'' when status LIKE ''%PASS%'' then ''u-color-39-bg'' ELSE ''u-info-bg'' END ) status_color,',
'       (CASE WHEN buyer is not null  THEN ''<span aria-hidden="true" class="fa fa-user"></span>''  ELSE null END ) buyer_icon',
'  FROM TABLE( get_sellerauctions_data( :P15_ID ) )',
' WHERE auctioncontainer_id = :P15_AUCTIONCONTAINER_ID',
' GROUP BY status,',
'          product_id,',
'          buyer,',
'          ar_sa,',
'          sakNo,',
'          startPrice,',
'          lastBid,',
'          isTransferToInfath,',
'          paymentStatus,',
'          subTotal,',
'          totalPrice,',
'          totalDiscount',
' ORDER BY status DESC;'))
