wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(103756965448171558)
,p_plug_name=>'SELLER AUCTIONS'
,p_region_name=>'SELLER_AUCTIONS'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(73888850119277902)
,p_plug_display_sequence=>50
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
' SELECT',
'    id,',
'    successfulproductscount,',
'    productscount,',
'    name,',
'    type,',
'    round(( successfulproductscount / productscount * 100 ),3)|| '' % '' AS sale_percentage,',
'    auctioncontainer_id,',
'    SUM(nvl(won_price, 0))   won_price,',
'    SUM(nvl(agent_price, 0)) agent_price ,       ',
'    null as details ,        ',
'    null as Close',
'  from (        ',
'',
'    SELECT',
'      id,',
'    successfulproductscount,',
'    productscount,',
'    name,',
unistr('    DECODE(type, ''TIMED'', ''\0632\0645\0646\064A'', ''INFATH_TIMED'', ''\0632\0645\0646\064A \0646\0641\0627\0630'', ''\062D\0636\0648\0631\064A'') AS type,'),
'    auctioncontainer_id,',
unistr('    (case when item_ar_SA like ''%\0633\0639\0631 \0627\0644\0631\0628\062D%'' then nvl(item_totalPrice,0) else 0 end) won_price,'),
unistr('    (CASE WHEN item_ar_sa LIKE ''%\0633\0639\064A%'' THEN nvl( item_totalprice, 0) ELSE 0 END ) agent_price          '),
'FROM TABLE ( get_sellerauctions_data(:P15_ID) ))',
'group by id,',
'    successfulproductscount,',
'    productscount,',
'    name,',
'    type,',
'    auctioncontainer_id',
'',
'',
'/*',
'SELECT',
'    id,',
'    successfulproductscount,',
'    productscount,',
'    name,',
'    type,',
'    round(( successfulproductscount / productscount * 100 ),3)|| '' % ''                 sale_percentage,',
'    auctioncontainer_id,',
'    SUM(nvl(won_price, 0))   won_price,',
'    SUM(nvl(agent_price, 0)) agent_price ,       ',
'    null as details from (        ',
'',
'    SELECT',
'    distinct id,',
'    successfulproductscount,',
'    productscount,',
'    name,',
'    type,',
'    auctioncontainer_id,',
unistr('    (case when item_ar_SA like ''%\0633\0639\0631 \0627\0644\0631\0628\062D%'' then SUM(nvl(item_totalPrice,0)) else 0end) won_price,'),
unistr('    (CASE WHEN item_ar_sa LIKE ''%\0633\0639\064A%''       THEN SUM( nvl( item_totalprice, 0)) ELSE 0 END ) agent_price          '),
'FROM',
'    TABLE ( get_sellerauctions_data(:P15_ID) ) ',
'',
'    ',
'    group by id,',
