,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ID,',
'       SELLER_ID,',
'       COMMENT_TEXT,',
'       DECODE(CREATED_BY, :APP_USER, ''self'', ''other'') AS COMMENT_TEXT_CLASS,',
'       CREATED_BY AS USER_NAME,',
'       TO_CHAR(CREATED_DATE + 3/24, ''MM/DD/YYYY HH24:MI:SS'') AS COMMENT_DATE,',
'    --    ''<span aria-hidden="true" class="fa fa-user fa-2x"></span>'' AS USER_ICON,',
'       CREATED_BY AS USER_ICON,',
'       NULL AS ATTRIBUTE_1,',
'       NULL AS ATTRIBUTE_2,',
'       NULL AS ATTRIBUTE_3,',
'       NULL AS ATTRIBUTE_4,',
'       NULL AS ACTIONS',
'  FROM SELLERS_COMMENTS',
' WHERE SELLER_ID = :P21_SELLER_ID',
'ORDER BY 1 ASC'))
